import inspect
from os.path import relpath, dirname

for name in ["sphinx.ext.linkcode", "numpydoc.linkcode"]:
    try:
        __import__(name)
        extensions.append(name)
        break
    except ImportError:
        pass
else:
    print("NOTE: linkcode extension not found -- no links to source generated")


def linkcode_resolve(domain, info):
    """
    Determine the URL corresponding to Python object
    """
    if domain != "py":
        return None

    modname = info["module"]
    fullname = info["fullname"]

    submod = sys.modules.get(modname)
    if submod is None:
        return None

    obj = submod
    for part in fullname.split("."):
        try:
            obj = getattr(obj, part)
        except:
            return None

    try:
        fn = inspect.getsourcefile(obj)
    except:
        fn = None
    if not fn:
        return None

    try:
        source, lineno = inspect.findsource(obj)
    except:
        lineno = None

    if lineno:
        linespec = "#L%d" % (lineno + 1)
    else:
        linespec = ""

    fn = relpath(fn, start=dirname(pele.__file__))

    revision = os.environ.get("GITHUB_SHA", "docs-autogeneration")
    return "https://github.com/pele-python/pele/blob/{}/pele/{}{}".format(
        revision,
        fn,
        linespec,
    )


def setup(app):
    # References outside the selected Breathe classes use the complete Doxygen site.
    from docutils import nodes
    import posixpath
    import re

    xml_dir = Path(__file__).parent / breathe_projects["pele"]
    index = ET.parse(xml_dir / "index.xml").getroot()
    targets = {}
    names = {}
    for compound in index.findall("compound"):
        refid = compound.get("refid")
        target = f"doxygen/{refid}.html"
        targets[refid] = target
        name = compound.findtext("name")
        names[name] = target
        for member in compound.findall("member"):
            member_id = member.get("refid")
            target = f"doxygen/{refid}.html#{member_id.rsplit('_1', 1)[-1]}"
            targets[member_id] = target
            names[f"{name}::{member.findtext('name')}"] = target
            if member.get("kind") == "enumvalue":
                for enum in compound.findall("member[@kind='enum']"):
                    if member_id.startswith(enum.get("refid")):
                        names[f"{name}::{enum.findtext('name')}::{member.findtext('name')}"] = target

    def doxygen_reference(app, env, node, contnode):
        if app.builder.format != "html":
            return None
        target = None
        if node.get("refdomain") == "std" and node.get("reftype") == "ref":
            target = targets.get(node["reftarget"])
        elif node.get("refdomain") == "cpp":
            name = re.sub(r"<.*>", "", node["reftarget"])
            target = names.get(name) or names.get(f"pele::{name}")
        if target is None:
            return None
        source = app.builder.get_target_uri(node["refdoc"])
        uri = posixpath.relpath(target, posixpath.dirname(source) or ".")
        return nodes.reference("", "", contnode, refuri=uri)

    def dict_method_signature(app, what, name, obj, options, signature, return_annotation):
        # The builtin's first line includes prose after its return annotation.
        if obj is dict.update:
            return "([E, ]**F)", "None"
        if any(obj is method for method in (dict.clear, dict.copy, dict.items, dict.keys, dict.values)):
            return signature, None

    def int_bytes_docstring(app, what, name, obj, options, lines):
        # Python 3.12's inherited int docstrings use an unmatched quote.
        if name in ("pele.optimize.HessianType.from_bytes", "pele.optimize.HessianType.to_bytes",
                    "pele.optimize.StopCriterionType.from_bytes", "pele.optimize.StopCriterionType.to_bytes"):
            lines[:] = [line.replace("`sys.byteorder'", "``sys.byteorder``") for line in lines]

    source_targets = None

    def source_reference(app, env, node, contnode):
        nonlocal source_targets
        if node.get("refdomain") != "py" or app.builder.format != "html":
            return None
        if source_targets is None:
            entries = json.loads((Path(app.srcdir) / "generated/source_api/manifest.json").read_text())
            source_targets = {entry["fullname"]: entry for entry in entries}
        name = node["reftarget"]
        module = node.get("py:module") or ""
        cls = node.get("py:class") or ""
        entry = (source_targets.get(f"{module}.{cls}.{name}")
                 or source_targets.get(f"{module}.{name}") or source_targets.get(name))
        if entry is None:
            matches = [item for fullname, item in source_targets.items() if fullname.endswith("." + name)]
            nearby = [item for item in matches if item["fullname"].startswith(module.rsplit(".", 1)[0] + ".")]
            if len(nearby) == 1:
                entry = nearby[0]
            elif len(matches) == 1:
                entry = matches[0]
        if entry is None:
            return None
        uri = app.builder.get_relative_uri(node["refdoc"], entry["docname"]) + "#" + entry["anchor"]
        return nodes.reference("", "", contnode, refuri=uri)

    app.connect("missing-reference", doxygen_reference)
    app.connect("missing-reference", source_reference)
    app.connect("autodoc-process-signature", dict_method_signature, priority=100)
    app.connect("autodoc-process-docstring", int_bytes_docstring, priority=100)
